// DirectoryUserExists checks if the DirectoryUser row exists.
func DirectoryUserExists(ctx context.Context, exec boil.ContextExecutor, iD string) (bool, error) {
	var exists bool
	sql := "select exists(select 1 from \"directory_users\" where \"id\"=$1 limit 1)"

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, sql)
		fmt.Fprintln(writer, iD)
	}
	row := exec.QueryRowContext(ctx, sql, iD)

	err := row.Scan(&exists)
	if err != nil {
		return false, errors.Wrap(err, "dbpostgres: unable to check if directory_users exists")
	}

	return exists, nil
}

// Exists checks if the DirectoryUser row exists.
func (o *DirectoryUser) Exists(ctx context.Context, exec boil.ContextExecutor) (bool, error) {
	return DirectoryUserExists(ctx, exec, o.ID)
}
